package com.sobrenaturaldirector.planner.model;
import java.util.*;import com.sobrenaturaldirector.decision.DecisionResult;import com.sobrenaturaldirector.decision.model.DecisionContext;
public final class PlanningContext {private final DecisionResult decision;private final DecisionContext context;private final Map<String,Boolean> capabilities;private final boolean safetyKnown;private final Map<String,Double> budgets;private final long referenceTick;public PlanningContext(DecisionResult decision,DecisionContext context,Map<String,Boolean>capabilities,boolean safetyKnown,Map<String,Double>budgets,long tick){if(decision==null||context==null||tick<0)throw new IllegalArgumentException("invalid planning context");this.decision=decision;this.context=context;this.capabilities=Collections.unmodifiableMap(new TreeMap<String,Boolean>(capabilities==null?Collections.<String,Boolean>emptyMap():capabilities));this.safetyKnown=safetyKnown;this.budgets=Collections.unmodifiableMap(new TreeMap<String,Double>(budgets==null?Collections.<String,Double>emptyMap():budgets));referenceTick=tick;}public DecisionResult getDecision(){return decision;}public DecisionContext getContext(){return context;}public Map<String,Boolean>getCapabilities(){return capabilities;}public boolean isSafetyKnown(){return safetyKnown;}public Map<String,Double>getBudgets(){return budgets;}public long getReferenceTick(){return referenceTick;} }
